import {
  Button as AriaButton,
  Disclosure,
  DisclosureGroup,
  DisclosurePanel,
  Heading,
} from "react-aria-components";
import type {
  DisclosureGroupProps as AriaDisclosureGroupProps,
  DisclosureProps as AriaDisclosureProps,
} from "react-aria-components";
import { ChevronDown } from "./icons";
import { Children, createContext, useContext } from "react";
import type { ReactNode, Ref } from "react";
import "./Accordion.css";

// `variant` is set once on the group but every item has to render it (its own surface), and RAC
// hands the Disclosure no channel to read it from — same relay as Tabs/SegmentedControl.
export type AccordionVariant = "flat" | "contained";
export type AccordionSize = "small" | "medium" | "large";

// `size` takes the same relay as `variant`: set once on the group, rendered by every item.
const AccordionVariantContext = createContext<AccordionVariant>("flat");
const AccordionSizeContext = createContext<AccordionSize>("medium");

export interface AccordionProps
  extends Omit<AriaDisclosureGroupProps, "className"> {
  /**
   * Presentation form. "flat" (default) is a divider-separated list; "contained" gives each
   * item its own filled, rounded card.
   *
   * @default "flat"
   */
  variant?: AccordionVariant;
  /**
   * Item size: the trigger's height and padding, the chevron and the title (`subtitle-<size>`)
   * together. The panel is CONTENT and stays `body-medium` at every size (component-contract.md §7,
   * what a size reaches). `small` is for a dense tool panel.
   *
   * @default "medium"
   */
  size?: AccordionSize;
  /** Additional class. sd-accordion is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

/**
 * One CSS knob is public: `--sd-accordion-content-gap`, the gap your panel content is spaced at. Set
 * it on the Accordion (`style`) when that gap is wider than the trigger's padding: the panel raises its top
 * seam and its bottom padding to it. Unset, both seams are the component's own.
 */
export function Accordion({ variant = "flat", size = "medium", className, ...props }: AccordionProps) {
  return (
    <AccordionVariantContext.Provider value={variant}>
      <AccordionSizeContext.Provider value={size}>
        <DisclosureGroup
          {...props}
          data-variant={variant}
          className={className ? `sd-accordion ${className}` : "sd-accordion"}
        />
      </AccordionSizeContext.Provider>
    </AccordionVariantContext.Provider>
  );
}

export interface AccordionItemProps
  extends Omit<AriaDisclosureProps, "className" | "children"> {
  /** Title shown in the trigger. */
  title: ReactNode;
  /**
   * Panel content. Text-only content (strings and numbers) is wrapped in a paragraph that takes the
   * item's text inset (a contained card's, 0 when flat); anything else renders as given, and a
   * consumer wraps its own prose in the `Indent` Layout where it needs the offset.
   */
  children?: ReactNode;
  /**
   * Heading level for the title.
   *
   * The title is wrapped in a real `Heading`, because the ARIA APG accordion pattern requires
   * each header button to sit inside one. `Collapsible` borrows RAC's Disclosure, whose pattern
   * asks for no heading, and therefore renders none — that asymmetry is the difference between
   * the two components, not an oversight in either.
   *
   * @usageInvariant accordion-collapsible-heading
   * @default 3
   */
  headingLevel?: 1 | 2 | 3 | 4 | 5 | 6;
  /** Additional class. sd-accordion__item is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function AccordionItem({
  title,
  children,
  headingLevel = 3,
  className,
  ...props
}: AccordionItemProps) {
  const variant = useContext(AccordionVariantContext);
  const size = useContext(AccordionSizeContext);
  return (
    <Disclosure
      {...props}
      data-variant={variant}
      data-size={size}
      className={className ? `sd-accordion__item ${className}` : "sd-accordion__item"}
    >
      {({ isExpanded }) => (
        <>
          <Heading level={headingLevel}>
            <AriaButton
              slot="trigger"
              className="sd-accordion__trigger"
              data-expanded={isExpanded || undefined}
            >
              <span className={`sd-accordion__title sd-type-subtitle-${size}`}>{title}</span>
              <span
                aria-hidden="true"
                className="sd-accordion__chevron"
                data-expanded={isExpanded || undefined}
              >
                <ChevronDown size="1em" />
              </span>
            </AriaButton>
          </Heading>
          <DisclosurePanel className="sd-accordion__panel sd-type-body-medium">
            {isTextOnly(children) ? <p className="sd-accordion__panel-text">{children}</p> : children}
          </DisclosurePanel>
        </>
      )}
    </Disclosure>
  );
}

/** Whether the panel holds only text, which the component then draws as its own paragraph. */
function isTextOnly(content: ReactNode): boolean {
  const parts = Children.toArray(content);
  return parts.length > 0 && parts.every((p) => typeof p === "string" || typeof p === "number");
}

.sd-accordion {
  /* The consumer's content gap (the panel rule below), declared here so it starts unset at every
     Accordion; set it on this element through `style`. */
  --sd-accordion-content-gap: 0px;
  display: flex;
  flex-direction: column;
  width: 100%;
}
.sd-accordion[data-disabled] {
  opacity: var(--sd-state-disabled);
}
/* contained — each item becomes its own filled, rounded card, parted by a gap rather than the
   per-item divider. A flat group draws no leading rule either: whatever sits above it (a heading, a
   card's edge) already bounds it, and a rule there divides nothing. */
.sd-accordion[data-variant="contained"] {
  gap: var(--sd-accordion-gap-contained);
}

/* The size relay, on the item like the variant's: the trigger, chevron and panel read the
   `-current` value, so one attribute sets all four dimensions. `medium` is the default rung. */
.sd-accordion__item {
  --sd-accordion-trigger-min-height-current: var(--sd-accordion-trigger-min-height-medium);
  --sd-accordion-trigger-padding-block-current: var(--sd-accordion-trigger-padding-block-medium);
  --sd-accordion-chevron-height-current: var(--sd-accordion-chevron-height-medium);
  --sd-accordion-chevron-font-size-current: var(--sd-accordion-chevron-font-size-medium);
  --sd-accordion-panel-padding-block-end-current: var(--sd-accordion-panel-padding-block-end-medium);
  border-block-end: var(--sd-accordion-item-border-width) solid var(--sd-accordion-item-border);
}
.sd-accordion__item[data-size="small"] {
  --sd-accordion-trigger-min-height-current: var(--sd-accordion-trigger-min-height-small);
  --sd-accordion-trigger-padding-block-current: var(--sd-accordion-trigger-padding-block-small);
  --sd-accordion-chevron-height-current: var(--sd-accordion-chevron-height-small);
  --sd-accordion-chevron-font-size-current: var(--sd-accordion-chevron-font-size-small);
  --sd-accordion-panel-padding-block-end-current: var(--sd-accordion-panel-padding-block-end-small);
}
.sd-accordion__item[data-size="large"] {
  --sd-accordion-trigger-min-height-current: var(--sd-accordion-trigger-min-height-large);
  --sd-accordion-trigger-padding-block-current: var(--sd-accordion-trigger-padding-block-large);
  --sd-accordion-chevron-height-current: var(--sd-accordion-chevron-height-large);
  --sd-accordion-chevron-font-size-current: var(--sd-accordion-chevron-font-size-large);
  --sd-accordion-panel-padding-block-end-current: var(--sd-accordion-panel-padding-block-end-large);
}
/* The card's inset and corners are published as local intermediates the trigger and panel read
   (contract §6.5) — the alternative would be a descendant combinator, and stamping data-variant on
   four elements to avoid one.
   BOTH variants declare EVERY intermediate, rather than one setting them and the other relying on a
   `var(…, fallback)`: custom properties INHERIT, so a flat Accordion nested inside a contained
   panel picked up the card's 20px inset and corner and rendered as a card (measured). A fallback
   only fires when the property is undefined, and inheritance means it is not. */
.sd-accordion__item[data-variant="flat"] {
  --sd-accordion-padding-inline-current: 0;
  /* The item radius, not 0: a square hover tint runs flush to the column edge and reads as a fill
     cropped by its container. Nothing fills below a flat trigger, so its
     corners stay round when it is expanded too. */
  --sd-accordion-radius-current: var(--sd-accordion-item-radius);
  --sd-accordion-expanded-radius-current: var(--sd-accordion-item-radius);
  /* A flat item is a row whose only paint is its state fill: its title stands one text inset in like
     all text (ADR-0053) and the wash bleeds past the row by the overhang (contract §6 rule 8). */
  --sd-accordion-state-layer-overhang-current: var(--sd-accordion-trigger-state-layer-overhang);
  --sd-accordion-text-padding-inline-current: var(--sd-accordion-text-padding-inline);
  /* A flat trigger has no inset of its own, so an outward ring would run past the column edge its
     dividers end on and be cut by any scroller holding the list. Inset, it sits inside the trigger's
     own corner, on the column; the hover wash bleeds past it by the overhang. */
  --sd-accordion-focus-ring-inset-current: inset;
  /* The item, and so its divider, stays on the column: only the wash bleeds, from the trigger's own
     layer below, as Collapsible's does. A rule is not a fill, so it never runs past the text column
     (contract §6 rule 8). */
}
.sd-accordion__item[data-variant="contained"] {
  background: var(--sd-accordion-item-background-contained);
  border-radius: var(--sd-accordion-item-radius-contained);
  corner-shape: superellipse(var(--sd-radius-curve));
  border-block-end: 0;
  --sd-accordion-padding-inline-current: var(--sd-accordion-item-padding-inline-contained);
  --sd-accordion-radius-current: var(--sd-accordion-item-radius-contained);
  --sd-accordion-expanded-radius-current: 0;
  /* The card's own padding holds its content, and the layer stays inside the card. The card is a
     painted surface the component draws, so the text it draws there (title, chevron, the text-only
     panel content it wraps itself) takes the text inset (contract §6 rule 8, component-owned text). */
  --sd-accordion-state-layer-overhang-current: 0px;
  --sd-accordion-text-padding-inline-current: var(--sd-accordion-text-padding-inline);
  /* A card's trigger rings outward, on its own corner (empty: the ring's `inset` keyword, unset). */
  --sd-accordion-focus-ring-inset-current: ;
}

.sd-accordion__trigger {
  position: relative;
  display: flex;
  /* flex-start, not center: with a wrapping title, centring puts the chevron in the gap BETWEEN
     the two lines (measured 8.75px below the first line's centre). The chevron below is sized to
     one line of the title's role, so top-aligning lands it exactly on line one — the same
     first-line rule Checkbox/Radio/Switch already follow for their wrapping labels. */
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--sd-accordion-trigger-gap);
  width: 100%;
  min-height: var(--sd-accordion-trigger-min-height-current);
  padding-block: var(--sd-accordion-trigger-padding-block-current);
  /* Per-variant via the intermediates above: 0 for flat, the card inset for contained. */
  padding-inline: var(--sd-accordion-padding-inline-current);
  /* The card's corner, so the ::after state layer (border-radius: inherit) is clipped to it —
     without this the hover tint paints square over a 20px-rounded card. Clipping the item instead
     would have been one line, but `overflow: hidden` would also eat the focus ring of any control
     placed in the panel. */
  border-radius: var(--sd-accordion-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: var(--sd-accordion-trigger-background);
  color: var(--sd-accordion-trigger-foreground);
  border: 0;
  font: inherit;
  text-align: start;
  cursor: pointer;
  outline: none;
}
/* Interaction state-layer overlay (ADR-0009). A flat item's layer reaches PAST the trigger by the
   overhang, so the wash rounds away from a title that stays on the start line; a contained item's
   overhang is 0. */
.sd-accordion__trigger::after {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline: calc(-1 * var(--sd-accordion-state-layer-overhang-current));
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-accordion__trigger[data-hovered]::after {
  background: var(--sd-state-hover);
}
.sd-accordion__trigger[data-pressed]::after {
  background: var(--sd-state-pressed);
}
/* Expanded: in a contained card the panel continues below, so the header is no longer the card's
   bottom edge; a flat item keeps its corners (the intermediate above). */
.sd-accordion__trigger[data-expanded] {
  border-end-start-radius: var(--sd-accordion-expanded-radius-current);
  corner-end-start-shape: superellipse(var(--sd-radius-curve));
  border-end-end-radius: var(--sd-accordion-expanded-radius-current);
  corner-end-end-shape: superellipse(var(--sd-radius-curve));
}
.sd-accordion__trigger[data-disabled] {
  cursor: not-allowed;
  opacity: var(--sd-state-disabled);
}
/* Only the focused control rings: the trigger itself, never the item or panel around a control
   focused inside them, so a field in an open panel shows its own ring alone. The ring follows the
   trigger's corner (square below the header of an expanded card). */
.sd-accordion__trigger[data-focus-visible] {
  box-shadow: var(--sd-accordion-focus-ring-inset-current) 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

/* The title takes the item's text inset: 0 in a flat item, the component-owned inset on a contained
   card (the relays above). Start edge only. */
.sd-accordion__title {
  padding-inline-start: var(--sd-accordion-text-padding-inline-current);
  color: var(--sd-accordion-title-foreground);
}

/* The chevron mirrors the title's inset at the end edge: a bare glyph on the card crowds its curve
   as text does. MARGIN, not padding: the expanded rule below rotates this element 180°, and a
   transform rotates the padding with it, so the glyph shifted on every toggle (measured 24 collapsed
   / 16 expanded). Margin positions the box before the transform, which spins about its own centre. */
.sd-accordion__chevron {
  flex: 0 0 auto;
  margin-inline-end: var(--sd-accordion-text-padding-inline-current);
  color: var(--sd-accordion-chevron-foreground);
  /* A flex box exactly one title-line tall: `display: flex` drops the inline-baseline descender
     that made the box 21px for a 16px glyph, and the explicit height is what `flex-start` above
     aligns to. The glyph then centres inside its own line box. */
  display: flex;
  align-items: center;
  height: var(--sd-accordion-chevron-height-current);
  font-size: var(--sd-accordion-chevron-font-size-current);
  transition: transform var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-accordion__chevron[data-expanded] {
  transform: rotate(180deg);
}

.sd-accordion__panel {
  padding-inline: var(--sd-accordion-padding-inline-current);
  color: var(--sd-accordion-panel-foreground);
  outline: none;
}
/* Bottom padding only: the trigger above already ends with its own 16, so a matching top here
   would stack to 32 between a title and the content it introduces. No `padding-block-start` rule
   at all rather than a zero token — 0 is the initial value, and a token that is always 0 is noise
   in the manifest, in Figma, and in the docs.
   Guarded on `:not([hidden])` because React Aria collapses the panel with `hidden="until-found"`
   (so find-in-page can reveal it), and that is `content-visibility: hidden`, NOT `display: none` —
   the box survives, so an unguarded bottom padding renders as 16px of dead space under EVERY
   collapsed row (measured 75px against a 58px trigger). Same element, so no descendant combinator. */
.sd-accordion__panel:not([hidden]) {
  /* Both seams are right when the content is spaced at the trigger's own rung. A consumer whose
     content is spaced wider sets `--sd-accordion-content-gap` to that gap on the Accordion (declared 0
     on the root above; not a token, so unset means unset). The top seam then adds
     only what the trigger's padding leaves short, so the head binds to its content at least as
     tightly as the content binds to itself (attachment), and the bottom seam rises to the gap,
     since across the item's divider the gap may equal the content's own and never be tighter
     (token-contract.md § By relationship, an edge is a step). It is not
     `--sd-accordion-trigger-gap`: that is also the title-to-chevron token, so it is never unset. */
  padding-block-start: max(0px, calc(var(--sd-accordion-content-gap) - var(--sd-accordion-trigger-padding-block-current)));
  padding-block-end: max(var(--sd-accordion-panel-padding-block-end-current), var(--sd-accordion-content-gap));
}
/* panel-text: the paragraph AccordionItem wraps text-only children in, so it is text the component
   draws, and on a contained card it takes the card's text inset (0 when flat). Not a class for
   consumers: content they place is wrapped in the `Indent` Layout if it needs the offset. */
.sd-accordion__panel-text {
  margin: 0;
  padding-inline: var(--sd-accordion-text-padding-inline-current);
}

@media (prefers-reduced-motion: reduce) {
  .sd-accordion__chevron {
    transition: none;
  }
}
